Definition IB_STACK : Z := 64.

Definition ib_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (n : Z) (ns' : NS) (lo : Z) (X : list Z) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m',
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz n) a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom rsegs)
    /\ munch (ibW lo (bv_unsigned sp) X) m m' /\ wmono rsegs m m' /\ mem_inv rsegs m'
    /\ stk rsegs m' lo (bv_unsigned sp)
    /\ NSR m' ns' lo (bv_unsigned sp) X.

Definition ib_stmt : Prop := forall (h pos n : Z) (ns ns' : NS) (fuel : nat) (lo : Z) (X : list Z)
    ra sp gp tp t0 t1 t2 s0 s1 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem),
  NSR m ns lo (bv_unsigned sp) X -> is_Some (ns !! h) -> is_Some (ns !! pos) -> is_Some (ns !! n) ->
  rb_insert_before fuel ns h pos n = Some ns' ->
  stk rsegs m lo (bv_unsigned sp) -> lo + IB_STACK <= bv_unsigned sp -> hceil <= lo ->
  mem_inv rsegs m ->
  evt rsegs (ib_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc n ns' lo X m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz h) (wz pos) (wz n) a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_RB_INSERT_BEFORE) fc None m (seg_rom rsegs)).
Scheme kc__1 := Elimination for Corelib.Init.Datatypes.option Sort Prop.
Scheme kc__2 := Elimination for Corelib.Init.Logic.and Sort Prop.
Scheme kc__3 := Elimination for Corelib.Init.Logic.ex Sort Prop.
Scheme kc__4 := Elimination for Corelib.Init.Datatypes.bool Sort Prop.

