Lemma ib_from_ec8 : forall (h pos n prev : Z) (ns ns1 ns' : NS) (fuel : nat) (lo : Z) (X : list Z) (ll : bool) (nd : Z)
    (ra sp : word) gp tp (x1 t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 s2v s1v s0v s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word)
    (F : bvmap 5 word) fc (m m1 : mem) (j16 : list byte),
  NSR m1 ns lo (bv_unsigned sp) X ->
  (get_parent ns h ≫= (λ hp, if hp =? 0 then Some (true, pos)
                            else get_left ns pos ≫= (λ pl, Some (if pl =? 0 then (true, pos) else (false, prev))))) = Some (ll, nd) ->
  insert_commit ns h n ll nd = Some ns1 ->
  rebalance_after_insertion fuel ns1 h n = Some ns' ->
  rw_cells rsegs m1 (bv_unsigned sp + -48) [CB 16 j16; C8 s2v; C8 s1v; C8 s0v; C8 ra] ->
  stk rsegs m1 lo (bv_unsigned sp + -48) -> lo + 64 <= bv_unsigned sp -> hceil <= lo ->
  munch (ibW lo (bv_unsigned sp) X) m m1 -> wmono rsegs m m1 -> mem_inv rsegs m1 ->
  0 <= h < 2^64 -> 0 <= pos < 2^64 -> 0 <= n < 2^64 ->
  evt rsegs (ib_post ra sp gp tp s0v s1v s2v s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc n ns' lo X m)
    (MS (mkR x1 (Z_to_bv 64 (bv_unsigned sp + -48)) gp tp t0 t1 t2 (Z_to_bv 64 n) (Z_to_bv 64 h) (Z_to_bv 64 prev) a1 a2 a3 a4 a5 a6 a7
              (Z_to_bv 64 pos) s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 0x33d30) fc None m1 (seg_rom rsegs)).
